UPDATE cage_cell_index
SET animal_cage_id = #{animalCageId}, synced_at = NOW()
WHERE shelf_index_id = #{shelfIndexId}
  AND position_x = #{positionX}
  AND position_y = #{positionY}

mapper.select:
SELECT si.id AS shelfIndexId, si.shelve_id AS shelveId, si.shelve_name AS shelveName, si.room_id AS roomId, si.room_name AS roomName, si.campus_name AS campusName, si.area_name AS areaName, si.floor_name AS floorName, COUNT(cci.id) AS totalCells, SUM(CASE WHEN cci.animal_cage_id IS NOT NULL THEN 1 ELSE 0 END) AS syncedCells, SUM(CASE WHEN cci.has_cage_box = 1 THEN 1 ELSE 0 END) AS boundCells, MAX(cci.synced_at) AS lastSyncedAt FROM cage_shelf_index si LEFT JOIN cage_cell_index cci ON cci.shelf_index_id = si.id WHERE si.deleted = 0
AND si.room_id = #{roomId}
AND (si.shelve_name LIKE CONCAT('%', #{keyword}, '%') OR si.room_name LIKE CONCAT('%', #{keyword}, '%') OR si.campus_name LIKE CONCAT('%', #{keyword}, '%'))
GROUP BY si.id, si.shelve_id, si.shelve_name, si.room_id, si.room_name, si.campus_name, si.area_name, si.floor_name ORDER BY si.campus_name, si.area_name, si.floor_name, si.room_name, si.shelve_name LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(DISTINCT si.id) FROM cage_shelf_index si WHERE si.deleted = 0
AND si.room_id = #{roomId}
AND (si.shelve_name LIKE CONCAT('%', #{keyword}, '%') OR si.room_name LIKE CONCAT('%', #{keyword}, '%'))
